/** 엄격한 Assertion 컨테이너 */
export class AssertionCollector {
  constructor(caseName) {
    this.caseName = caseName;
    this.records = [];
    this.seenIds = new Set();
  }

  /** 실제 값 동등 비교 (caller pass 인자 없음) */
  expectEqual(id, expected, actual, meta = {}) {
    if (this.seenIds.has(id)) {
      throw new Error(`[중복 Assertion ID] '${id}' 가 이미 기록되었습니다.`);
    }
    this.seenIds.add(id);

    if (expected === undefined || actual === undefined) {
      const err = new Error(`[Assertion 실패: ${id}] expected 또는 actual이 undefined입니다.`);
      this.records.push({ id, expected, actual, pass: false, error: err.message, ...meta });
      throw err;
    }
    if (typeof expected === "number" && Number.isNaN(expected)) {
      const err = new Error(`[Assertion 실패: ${id}] expected가 NaN입니다.`);
      this.records.push({ id, expected, actual, pass: false, error: err.message, ...meta });
      throw err;
    }
    if (typeof actual === "number" && Number.isNaN(actual)) {
      const err = new Error(`[Assertion 실패: ${id}] actual이 NaN입니다.`);
      this.records.push({ id, expected, actual, pass: false, error: err.message, ...meta });
      throw err;
    }

    let pass = false;
    let error = null;
    try {
      assert.deepStrictEqual(actual, expected);
      pass = true;
    } catch (e) {
      pass = false;
      error = e.message;
    }

    this.records.push({ id, expected, actual, pass, error, ...meta });
    if (!pass) {
      throw new Error(`[Assertion 실패: ${id}] expected=${JSON.stringify(expected)}, actual=${JSON.stringify(actual)}`);
    }
  }

  /** 수치 및 크기 근사 비교 (caller pass 인자 없음) */
  expectNear(id, expected, actual, tolerance = 1, meta = {}) {
    if (this.seenIds.has(id)) {
      throw new Error(`[중복 Assertion ID] '${id}' 가 이미 기록되었습니다.`);
    }
    this.seenIds.add(id);

    if (typeof expected !== "number" || typeof actual !== "number" || Number.isNaN(expected) || Number.isNaN(actual)) {
      const err = new Error(`[Assertion 실패: ${id}] expected(${expected}) 또는 actual(${actual})이 유효한 숫자가 아닙니다.`);
      this.records.push({ id, expected, actual, pass: false, error: err.message, ...meta });
      throw err;
    }

    const diff = Math.abs(expected - actual);
    const pass = diff <= tolerance;
    const error = pass ? null : `차이(${diff})가 허용오차(${tolerance})를 초과했습니다.`;

    this.records.push({ id, expected, actual, pass, diff, tolerance, error, ...meta });
    if (!pass) {
      throw new Error(`[Assertion 실패: ${id}] expected=${expected}, actual=${actual} (허용오차: ${tolerance}, 실제차이: ${diff})`);
    }
  }

  /** 필수 Assertion 집합 검증 (누락된 ID가 있으면 throw) */
  validateRequiredCoverage() {
    const required = REQUIRED_ASSERTIONS[this.caseName] || [];
    const missing = [];
    for (const reqId of required) {
      if (!this.seenIds.has(reqId)) {
        missing.push(reqId);
      }
    }
    if (missing.length > 0) {
      throw new Error(`[필수 Assertion 누락: ${this.caseName}] 다음 필수 항목이 검증되지 않았습니다: ${missing.join(", ")}`);
    }
  }

  toJSON() {
    return this.records;
  }
}

