/** Bridge 요청 바디(인자 배열)에서 쿼리 객체 추출 */
export function parseBridgeQuery(request) {
  const postData = request.postData();
  if (!postData) return {};
  let body;
  try {
    body = JSON.parse(postData);
  } catch {
    return {};
  }
  if (!Array.isArray(body)) {
    throw new Error("Bridge 요청 바디는 JSON 인자 배열이어야 합니다.");
  }
  return body[0] || {};
}

/** 지연 응답(Held Route) 수명주기 컨트롤러 */
export class HeldRouteController {
  constructor(timeoutMs = 15000) {
    this.timeoutMs = timeoutMs;
    this.startedResolve = null;
    this.completedResolve = null;
    this.releaseHandler = null;

    this.startedPromise = new Promise((resolve) => {
      this.startedResolve = resolve;
    });
    this.completedPromise = new Promise((resolve) => {
      this.completedResolve = resolve;
    });

    this.isStarted = false;
    this.isReleased = false;
    this.isCompleted = false;
  }

  handle(route) {
    this.isStarted = true;
    if (this.startedResolve) this.startedResolve();

    return new Promise((resolve) => {
      this.releaseHandler = async (fulfillData) => {
        this.isReleased = true;
        try {
          await route.fulfill(fulfillData);
        } finally {
          this.isCompleted = true;
          if (this.completedResolve) this.completedResolve();
          resolve();
        }
      };
    });
  }

  async waitForStart() {
    let timer;
    const timeout = new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error(`Held 요청 시작 대기 시간 초과 (${this.timeoutMs}ms)`)), this.timeoutMs);
    });
    try {
      await Promise.race([this.startedPromise, timeout]);
    } finally {
      clearTimeout(timer);
    }
  }

  async release(fulfillData) {
    if (!this.releaseHandler) {
      throw new Error("Held 요청이 아직 시작되지 않아 해제할 수 없습니다.");
    }
    await this.releaseHandler(fulfillData);
  }

  async waitForComplete() {
    let timer;
    const timeout = new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error(`Held 핸들러 완료 대기 시간 초과 (${this.timeoutMs}ms)`)), this.timeoutMs);
    });
    try {
      await Promise.race([this.completedPromise, timeout]);
    } finally {
      clearTimeout(timer);
    }
  }
}

