/** 포트 사전 점검 (타 프로세스 충돌 방지, 타 PID 요청 0) */
async function checkPortAvailable(port) {
  return new Promise((resolve, reject) => {
    const s = net.createServer();
    s.once("error", (err) => {
      if (err.code === "EADDRINUSE") {
        reject(new Error(`포트 ${port}이 이미 점유되어 있습니다.`));
      } else {
        reject(err);
      }
    });
    s.once("listening", () => s.close(() => resolve(true)));
    s.listen(Number(port), "127.0.0.1");
  });
}

/** 소유 격리 서버 수명 관리 */
class OwnedServerManager {
  constructor() {
    this.tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "shiftmgmt-gemini-32v-"));
    this.process = null;
    this.bootstrapFile = path.join(this.tempDir, "data", "bootstrap-credentials.json");
    this.serverListeningConfirmed = false;
  }

  async start() {
    await checkPortAvailable(PORT);

    const env = { ...process.env };
    for (const k of Object.keys(env)) {
      if (k.startsWith("SHIFTMGMT_") || k.startsWith("SHIFT_")) delete env[k];
    }
    env.SHIFTMGMT_USER_DATA_DIR = this.tempDir;
    env.SHIFTMGMT_PORT = PORT;
    env.SHIFTMGMT_UI_BOOTSTRAP_FILE = this.bootstrapFile;

    this.process = spawn(process.execPath, [path.join(repoRoot, "dist/server/main/server.js")], {
      cwd: repoRoot,
      env,
      windowsHide: true,
      stdio: ["ignore", "pipe", "pipe"],
    });

    this.process.stdout.on("data", (chunk) => {
      const text = chunk.toString();
      if (text.includes(`http://127.0.0.1:${PORT}`) && text.includes(this.tempDir)) {
        this.serverListeningConfirmed = true;
      }
    });

    let ready = false;
    for (let i = 0; i < 150; i++) {
      if (this.process.exitCode !== null) throw new Error("격리 서버가 즉시 종료되었습니다.");
      if (this.serverListeningConfirmed) {
        try {
          const res = await fetch(`${BASE_URL}api/health`, { signal: AbortSignal.timeout(1000) });
          if (res.ok) {
            if (!fs.existsSync(this.bootstrapFile)) {
              await fetch(`${BASE_URL}api/auth:sign-in`, {
                method: "POST",
                headers: { "Content-Type": "application/json", Origin: BASE_URL.slice(0, -1) },
                body: JSON.stringify([{ loginId: "admin", password: DEFAULT_ADMIN_BOOTSTRAP_PASSWORD }]),
                signal: AbortSignal.timeout(10000),
              });
            }
            if (fs.existsSync(this.bootstrapFile)) {
              ready = true;
              break;
            }
          }
        } catch {}
      }
      await new Promise((r) => setTimeout(r, 100));
    }

    if (!ready) throw new Error("소유 서버 시작 및 준비 확인 실패");
  }

  async stop() {
    if (this.process && this.process.exitCode === null) {
      this.process.kill();
      await new Promise((resolve) => {
        const timer = setTimeout(resolve, 5000);
        this.process.once("exit", () => {
          clearTimeout(timer);
          resolve();
        });
      });
    }

    const realTemp = fs.realpathSync(this.tempDir);
    const osTemp = fs.realpathSync(os.tmpdir());
    if (path.dirname(realTemp) !== osTemp || !path.basename(realTemp).startsWith("shiftmgmt-gemini-32v-")) {
      throw new Error("소유 격리 디렉토리 경계 불일치: " + realTemp);
    }
    fs.rmSync(realTemp, { recursive: true, force: true, maxRetries: 5, retryDelay: 150 });
    if (fs.existsSync(realTemp)) {
      throw new Error("격리 디렉토리 삭제 확인 실패: " + realTemp);
    }
  }
}

/** 자식 프로세스 실행 (유한 타임아웃) */
async function runChildProcess(cmd, args, env, timeoutMs = 120000) {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, {
      cwd: repoRoot,
      env,
      windowsHide: true,
      stdio: ["ignore", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";

    child.stdout.on("data", (d) => {
      stdout += d.toString();
    });
    child.stderr.on("data", (d) => {
      stderr += d.toString();
    });

    let timer = setTimeout(() => {
      child.kill();
      reject(new Error(`자식 프로세스 실행 시간 초과 (${timeoutMs}ms)`));
    }, timeoutMs);

    child.on("error", (err) => {
      clearTimeout(timer);
      reject(err);
    });

    child.on("close", (code) => {
      clearTimeout(timer);
      resolve({ code: code ?? 1, stdout, stderr });
    });
  });
}

