    childResult = await runChildProcess(
      process.execPath,
      [...process.execArgv, path.join(repoRoot, "scripts/ui-checks/access-history-positive.mjs"), `--case=${selectedCase}`],
      childEnv
    );
  }

  if (childResult.code !== 0) {
    process.stderr.write(childResult.stderr || childResult.stdout || "");
    throw new Error(`자식 검증 프로세스 비정상 종료 (코드: ${childResult.code})`);
  }

  overallPass = true;
} catch (err) {
  executionError = err;
  overallPass = false;
} finally {
  if (server) {
    try {
      await server.stop();
    } catch (cleanErr) {
      cleanupErrors.push(cleanErr.message);
    }
  }

  const tempCleaned = cleanupErrors.length === 0;
  const finalPass = overallPass && tempCleaned;

  const manifestPath = path.join(runDir, "owner-final.json");
  try {
    fs.writeFileSync(
      manifestPath,
      JSON.stringify(
        {
          label: `access-history-${selectedCase}`,
          status: finalPass ? "PASS" : "FAIL",
          exitCode: finalPass ? 0 : 1,
          tempCleaned,
          executionError: executionError ? executionError.message : null,
          cleanupErrors,
          childExitCode: childResult?.code ?? null,
        },
        null,
        2
      )
    );
  } catch {}

  console.log(
    JSON.stringify({
      label: `access-history-${selectedCase}`,
      status: finalPass ? "PASS" : "FAIL",
      exitCode: finalPass ? 0 : 1,
      tempCleaned,
    })
  );

  process.exitCode = finalPass ? 0 : 1;
}

